//! Edition-2 row statement known answers, v4: v3 (CC 2.6.1, rc20 0c9e17c,
//! the clean mesh; family cases under CIRISConstitution v1.0-rc20 d4bd2a6;
//! CIRISVerify#326) with two rc21 rulings: each key's own holder signs its
//! `key:record` (CC 2.4.1.1), so a record only another key signed waits on the
//! key's own voice; and a free-form body carries a non-integral number as a
//! normalised tag-4 decimal, any number outside CBOR's integer range being
//! `body_number_unrepresentable` (CC 2.6.1.4).
//!
//! `tests/vectors/edition2/row_statements_v4.json` was generated by
//! `gen_row_statements_v4.py` beside it, with its own CBOR encoder over
//! dilithium-py and pyca/cryptography, sharing no code with verify. Every
//! valid statement must verify with the ids the file states, must be the
//! byte-for-byte output of `sign_row_statement` (both sides sign
//! deterministically) and must also be valid under CC's vendored family
//! model; every refusal must give the stated verdict. Every case states the
//! level it is read at.
//!
//! The reader derives `act` (CC 2.6.1.9): each `key:record` / `licensure`
//! family case states the act derived from its statement, and
//! `family_vendored_groups` reads the voices of one counted row together.
//!
//! `row_statements_v1.json`, `_v2.json` and `_v3.json` stay beside it
//! unchanged for the readers that pinned them. Their replay is retired: v1's
//! because the clean mesh refuses its earlier-form row, v2's because its
//! family cases are read under the family model before v1.0-rc20, v3's
//! because its key-directory cases make a key live on a record another key
//! signed (see the README).
#![cfg(feature = "pqc")]

use std::collections::BTreeMap;

use ciris_crypto::composite::{CompositePublicKey, CompositeSigningKey};
use ciris_verify_core::cde;
use ciris_verify_core::edition2::family::{
    select::{Act, Group},
    statement_act, verify_group_row_in_family, verify_row_in_family, verify_row_in_family_as_given,
    verify_row_in_family_with, FamilyFault, FamilyModel, FamilyRule, FamilyVerdict, GroupFault,
    RoleParty, SelectContext, VendoredFamilyModel,
};
use ciris_verify_core::edition2::keys::{check_key_record, KeyRecordDirectory};
use ciris_verify_core::edition2::{
    classify_reference, sign_row_statement, thumbprint, verify_object_statement,
    verify_row_statement, Digest32, Invalid, MissingKey, ObjectVerdict, ReferenceForm, Verdict,
};
use serde_json::Value as J;

const FILE: &str = include_str!("vectors/edition2/row_statements_v4.json");

/// Assert every case of `section` states `level` (and `model`, where given).
fn assert_level(f: &J, section: &str, level: &str, model: Option<&str>) {
    let cases = f[section].as_array().unwrap();
    assert!(!cases.is_empty(), "{section}");
    for c in cases {
        assert_eq!(c["level"].as_str(), Some(level), "{section}/{}", c["id"]);
        if let Some(m) = model {
            assert_eq!(c["model"].as_str(), Some(m), "{section}/{}", c["id"]);
        }
    }
}

fn key(n: u8) -> CompositeSigningKey {
    CompositeSigningKey::from_seeds(&[n; 32], &[n.wrapping_add(100); 32])
}

fn dir(seeds: impl IntoIterator<Item = u8>) -> BTreeMap<Digest32, CompositePublicKey> {
    seeds
        .into_iter()
        .map(|n| {
            let k = key(n);
            (thumbprint(k.public_key()), k.public_key().clone())
        })
        .collect()
}

fn label(v: &Verdict) -> String {
    match v {
        Verdict::Valid(_) => "valid".into(),
        Verdict::Waiting { missing } if missing.len() == 1 => match &missing[0] {
            MissingKey::Kid(k) => format!("waiting:kid:{}", hex::encode(k)),
            MissingKey::Voice { kid, .. } => format!("waiting:voice:{}", hex::encode(kid)),
            MissingKey::CoveringRecord { kid, at_ms } => {
                format!("waiting:covering_record:{}:{at_ms}", hex::encode(kid))
            },
            other => format!("waiting:{other:?}"),
        },
        Verdict::Waiting { .. } => "waiting".into(),
        Verdict::Invalid(i) => match i {
            Invalid::NotDeterministic { part, .. } => format!("invalid:not_deterministic:{part}"),
            Invalid::NotCoseSign1 => "invalid:not_cose_sign1".into(),
            Invalid::Malformed { member } => format!("invalid:malformed:{member}"),
            Invalid::UnexpectedMember { within } => format!("invalid:unexpected:{within}"),
            Invalid::TimeDisagreement { claim } => format!("invalid:time:{claim}"),
            Invalid::SetOrder { member } => format!("invalid:set_order:{member}"),
            Invalid::KidMismatch => "invalid:kid_mismatch".into(),
            Invalid::BadSignature => "invalid:bad_signature".into(),
            Invalid::KeyNotValid => "invalid:key_not_valid".into(),
            Invalid::DisclosureUnmatched => "invalid:disclosure_unmatched".into(),
            Invalid::DuplicateDigest => "invalid:duplicate_digest".into(),
            Invalid::UnregisteredFamily => "invalid:unregistered_family".into(),
            Invalid::DimensionFamily => "invalid:dimension_family".into(),
            Invalid::DimensionRefused { token } => format!("invalid:dimension_refused:{token}"),
            Invalid::DimensionUnregistered => "invalid:dimension_unregistered".into(),
            Invalid::BodyNumberUnrepresentable => "invalid:body_number_unrepresentable".into(),
            other => format!("invalid:{other:?}"),
        },
    }
}

fn hx(v: &J) -> Vec<u8> {
    hex::decode(v.as_str().unwrap()).unwrap()
}

#[test]
fn valid_statements_verify_and_match_our_producer() {
    let f: J = serde_json::from_str(FILE).unwrap();
    let cases = f["valid"].as_array().unwrap();
    assert!(!cases.is_empty());
    for c in cases {
        let id = c["id"].as_str().unwrap();
        let n = c["key_seed"].as_u64().unwrap() as u8;
        let bytes = hx(&c["statement_hex"]);
        let Verdict::Valid(v) = verify_row_statement(&bytes, &dir([n])) else {
            panic!("{id}: {:?}", verify_row_statement(&bytes, &dir([n])));
        };
        assert_eq!(hex::encode(v.kid), c["kid_hex"].as_str().unwrap(), "{id}");
        assert_eq!(v.iss, c["iss"].as_str().unwrap(), "{id}");
        assert_eq!(
            hex::encode(v.row_id),
            c["row_id_hex"].as_str().unwrap(),
            "{id}"
        );
        assert_eq!(
            hex::encode(v.statement_id),
            c["statement_id_hex"].as_str().unwrap(),
            "{id}"
        );

        // Re-mint with verify's producer from the decoded parts: the same bytes.
        let top = cde::decode(&bytes).unwrap();
        let cde::Value::Tag(_, inner) = top else {
            panic!()
        };
        let unprot = inner.as_array().unwrap()[1].as_map().unwrap().to_vec();
        let ours = sign_row_statement(
            &key(n),
            &v.iss,
            &v.sub,
            &v.row_type,
            &v.family,
            &v.payload,
            unprot,
        )
        .unwrap();
        assert_eq!(
            hex::encode(ours),
            hex::encode(&bytes),
            "{id}: producer differs"
        );
    }
}

#[test]
fn every_refusal_gives_its_verdict() {
    let f: J = serde_json::from_str(FILE).unwrap();
    let cases = f["refusals"].as_array().unwrap();
    assert!(!cases.is_empty());
    for c in cases {
        let id = c["id"].as_str().unwrap();
        let held = c["held_key_seeds"]
            .as_array()
            .unwrap()
            .iter()
            .map(|n| n.as_u64().unwrap() as u8);
        let got = verify_row_statement(&hx(&c["statement_hex"]), &dir(held));
        assert_eq!(label(&got), c["expect"].as_str().unwrap(), "{id}");
    }
}

#[test]
fn disclosed_digests() {
    let f: J = serde_json::from_str(FILE).unwrap();
    for c in f["valid"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|c| c.get("disclosed_digests_hex").is_some())
    {
        let n = c["key_seed"].as_u64().unwrap() as u8;
        let Verdict::Valid(v) = verify_row_statement(&hx(&c["statement_hex"]), &dir([n])) else {
            panic!("{}", c["id"]);
        };
        let mut got: Vec<String> = v
            .disclosures
            .iter()
            .map(|d| hex::encode(d.digest))
            .collect();
        got.sort();
        let want: Vec<String> = c["disclosed_digests_hex"]
            .as_array()
            .unwrap()
            .iter()
            .map(|x| x.as_str().unwrap().to_owned())
            .collect();
        assert_eq!(got, want, "{}", c["id"]);
    }
}

#[test]
fn every_case_states_its_level() {
    let f: J = serde_json::from_str(FILE).unwrap();
    assert_level(&f, "valid", "statement", None);
    assert_level(&f, "refusals", "statement", None);
    assert_level(&f, "key_directory", "statement", None);
    assert_level(&f, "family", "family", Some("test"));
    assert_level(&f, "family_vendored", "family", Some("vendored"));
    assert_level(&f, "family_vendored_groups", "family", Some("vendored"));
    assert_level(&f, "objects", "object", None);
    assert_level(&f, "key_records", "payload", None);
    assert_level(&f, "references", "value", None);
    // The clean mesh: no earlier-form names, no key held in part.
    assert!(f.get("earlier_form").is_none());
    assert!(f["key_directory"]
        .as_array()
        .unwrap()
        .iter()
        .all(|c| c.get("partial").is_none() && c["id"] != "held_in_part"));
}

/// Every valid statement is also valid at the family level under CC's
/// vendored model, with no caller-supplied selector keys.
#[test]
fn valid_statements_are_valid_under_the_vendored_model() {
    let f: J = serde_json::from_str(FILE).unwrap();
    for c in f["valid"].as_array().unwrap() {
        let id = c["id"].as_str().unwrap();
        assert_eq!(c["family_vendored_expect"].as_str(), Some("valid"), "{id}");
        let n = c["key_seed"].as_u64().unwrap() as u8;
        match verify_row_in_family(&hx(&c["statement_hex"]), &dir([n]), &VendoredFamilyModel) {
            FamilyVerdict::Valid { row, role: None } => {
                assert_eq!(
                    hex::encode(row.row_id),
                    c["row_id_hex"].as_str().unwrap(),
                    "{id}"
                );
            },
            other => panic!("{id}: {other:?}"),
        }
    }
}

/// `second_voice` is a second voice of the counted row `counted_with_refs`:
/// one row id, two statement ids, on a family CC's model counts.
#[test]
fn second_voice_is_a_voice_of_the_counted_row() {
    let f: J = serde_json::from_str(FILE).unwrap();
    let get = |id: &str| {
        f["valid"]
            .as_array()
            .unwrap()
            .iter()
            .find(|c| c["id"] == id)
            .unwrap()
            .clone()
    };
    let (counted, second) = (get("counted_with_refs"), get("second_voice"));
    assert_eq!(counted["row_id_hex"], second["row_id_hex"]);
    assert_ne!(counted["statement_id_hex"], second["statement_id_hex"]);
    assert_ne!(counted["kid_hex"], second["kid_hex"]);
    let n = counted["key_seed"].as_u64().unwrap() as u8;
    let Verdict::Valid(row) = verify_row_statement(&hx(&counted["statement_hex"]), &dir([n]))
    else {
        panic!()
    };
    assert_eq!(row.author, None);
    assert_eq!(
        VendoredFamilyModel.rule(&row.family).map(|r| r.authored),
        Some(false),
        "{} is counted in CC's model",
        row.family
    );
}

#[test]
fn key_record_end_rule() {
    let f: J = serde_json::from_str(FILE).unwrap();
    for c in f["key_records"].as_array().unwrap() {
        let id = c["id"].as_str().unwrap();
        let p = cde::decode(&hx(&c["payload_hex"])).unwrap();
        let got = match check_key_record(&p) {
            Ok(_) => "ok",
            Err(e) => e.token(),
        };
        assert_eq!(got, c["expect"].as_str().unwrap(), "{id}");
    }
}

#[test]
fn key_directory_cases() {
    let f: J = serde_json::from_str(FILE).unwrap();
    for c in f["key_directory"].as_array().unwrap() {
        let id = c["id"].as_str().unwrap();
        let mut d = KeyRecordDirectory::new();
        for r in c["records_hex"].as_array().unwrap() {
            d.insert(hx(r)).unwrap();
        }
        let got = verify_row_statement(&hx(&c["statement_hex"]), &d);
        assert_eq!(label(&got), c["expect"].as_str().unwrap(), "{id}");
    }
}

#[test]
fn family_cases() {
    let f: J = serde_json::from_str(FILE).unwrap();
    let model: BTreeMap<String, FamilyRule> = f["family_model"]
        .as_object()
        .unwrap()
        .iter()
        .map(|(k, v)| {
            let roles = v["roles"]
                .as_array()
                .unwrap()
                .iter()
                .map(|r| {
                    let party = match r[1].as_str().unwrap() {
                        "sub" => RoleParty::Sub,
                        m => RoleParty::Member(m.into()),
                    };
                    (r[0].as_str().unwrap().to_owned(), party)
                })
                .collect();
            (
                k.clone(),
                FamilyRule {
                    authored: v["authored"].as_bool().unwrap(),
                    roles,
                    scores_dimension: v["scores_dimension"].as_bool().unwrap(),
                },
            )
        })
        .collect();
    run_family_cases(&f["family"], &model);
}

#[test]
fn object_headers() {
    let f: J = serde_json::from_str(FILE).unwrap();
    for c in f["objects"].as_array().unwrap() {
        let id = c["id"].as_str().unwrap();
        let held = c["held_key_seeds"]
            .as_array()
            .unwrap()
            .iter()
            .map(|n| n.as_u64().unwrap() as u8);
        let got = match verify_object_statement(&hx(&c["statement_hex"]), &dir(held)) {
            ObjectVerdict::Valid(o) => {
                assert_eq!(
                    hex::encode(o.object_id),
                    c["object_id_hex"].as_str().unwrap(),
                    "{id}"
                );
                assert_eq!(
                    hex::encode(o.statement_id),
                    c["statement_id_hex"].as_str().unwrap(),
                    "{id}"
                );
                "valid".to_owned()
            },
            ObjectVerdict::Invalid(i) => label(&Verdict::Invalid(i)),
            ObjectVerdict::Waiting { missing } => label(&Verdict::Waiting { missing }),
        };
        assert_eq!(got, c["expect"].as_str().unwrap(), "{id}");
    }
}

#[test]
fn references_by_form() {
    let f: J = serde_json::from_str(FILE).unwrap();
    for c in f["references"].as_array().unwrap() {
        let id = c["id"].as_str().unwrap();
        let v = cde::decode(&hx(&c["cbor_hex"])).unwrap();
        let got = classify_reference(&v);
        match c["form"].as_str().unwrap() {
            "row" => assert_eq!(
                got.map(|r| match r {
                    ReferenceForm::Row(d) => hex::encode(d),
                    other => format!("{other:?}"),
                }),
                Some(c["digest_hex"].as_str().unwrap().to_owned()),
                "{id}"
            ),
            "key" => assert_eq!(
                got,
                Some(ReferenceForm::Key(
                    c["identity_ref"].as_str().unwrap().to_owned()
                )),
                "{id}"
            ),
            _ => assert_eq!(got, None, "{id}"),
        }
    }
}

/// A case's caller-supplied selector keys (CC's `family_select_vectors` form).
fn context(ctx: &J) -> SelectContext {
    SelectContext {
        verb: ctx.get("verb").map(|v| v.as_str().unwrap().to_owned()),
        identity: ctx.get("identity").map(|v| {
            v.as_array()
                .unwrap()
                .iter()
                .map(|x| x.as_str().unwrap().to_owned())
                .collect()
        }),
        group: ctx
            .get("group")
            .map(|v| Group::parse(v.as_str().unwrap()).unwrap()),
        seats: ctx.get("seats").map(|v| v.as_u64().unwrap()),
        act: ctx
            .get("act")
            .map(|v| Act::parse(v.as_str().unwrap()).unwrap()),
    }
}

fn held(c: &J) -> BTreeMap<Digest32, CompositePublicKey> {
    dir(c["held_key_seeds"]
        .as_array()
        .unwrap()
        .iter()
        .map(|n| n.as_u64().unwrap() as u8))
}

fn family_label(verdict: FamilyVerdict) -> String {
    match verdict {
        FamilyVerdict::Valid { role: None, .. } => "valid".to_owned(),
        FamilyVerdict::Valid { role: Some(r), .. } => format!("valid:role:{r}"),
        FamilyVerdict::FamilyInvalid(fault) => format!(
            "family_invalid:{}",
            match fault {
                FamilyFault::UnregisteredFamily => "unregistered_family",
                FamilyFault::AuthorColumn => "author_column",
                FamilyFault::IssNotInRole => "iss_not_in_role",
                FamilyFault::DimensionMissing => "dimension_missing",
                FamilyFault::AuthorshipUndetermined => "authorship_undetermined",
                FamilyFault::NoArmHolds => "no_arm_holds",
                _ => "other",
            }
        ),
        FamilyVerdict::Invalid(i) => label(&Verdict::Invalid(i)),
        other => format!("{other:?}"),
    }
}

fn run_family_cases(cases: &J, model: &dyn FamilyModel) {
    for c in cases.as_array().unwrap() {
        let id = c["id"].as_str().unwrap();
        let bytes = hx(&c["statement_hex"]);
        let ctx = c.get("ctx").map(context).unwrap_or_default();
        let verdict = match c.get("read").and_then(J::as_str) {
            None => match c.get("ctx") {
                None => verify_row_in_family(&bytes, &held(c), model),
                Some(_) => verify_row_in_family_with(&bytes, &held(c), model, &ctx),
            },
            Some("as_given") => verify_row_in_family_as_given(&bytes, &held(c), model, &ctx),
            Some(other) => panic!("{id}: read {other}"),
        };
        assert_eq!(family_label(verdict), c["expect"].as_str().unwrap(), "{id}");
        // The act the reader derives from the one statement.
        if let Some(act) = c.get("act").and_then(J::as_str) {
            let Verdict::Valid(row) = verify_row_statement(&bytes, &held(c)) else {
                panic!("{id}: statement not valid")
            };
            let derived = statement_act(&row).map(Act::as_str);
            match act {
                "own" | "group" => assert_eq!(derived, Some(act), "{id}"),
                "none" => assert_eq!(derived, None, "{id}"),
                // Nothing is derived; the statement alone would derive own.
                "withheld" => assert_eq!(c["read"].as_str(), Some("as_given"), "{id}"),
                other => panic!("{id}: act {other}"),
            }
        }
    }
}

#[test]
fn family_cases_under_the_vendored_model() {
    let f: J = serde_json::from_str(FILE).unwrap();
    let cases = &f["family_vendored"];
    run_family_cases(cases, &VendoredFamilyModel);
    // Every key:record / licensure case states the act derived from it.
    for c in cases.as_array().unwrap() {
        let id = c["id"].as_str().unwrap();
        if id.starts_with("v_key_record") || id.starts_with("v_licensure") || id == "v_author_signs"
        {
            assert!(c["act"].is_string(), "{id} states its act");
        }
    }
}

/// The statements of one counted row read together derive act `group`
/// (CC 2.6.1.9).
#[test]
fn family_groups_under_the_vendored_model() {
    let f: J = serde_json::from_str(FILE).unwrap();
    let cases = f["family_vendored_groups"].as_array().unwrap();
    assert!(cases.iter().any(|c| c["id"] == "g_key_record_counted"));
    for c in cases {
        let id = c["id"].as_str().unwrap();
        assert_eq!(c["act"].as_str(), Some("group"), "{id}");
        let sts: Vec<Vec<u8>> = c["statements_hex"]
            .as_array()
            .unwrap()
            .iter()
            .map(hx)
            .collect();
        let refs: Vec<&[u8]> = sts.iter().map(Vec::as_slice).collect();
        let got = verify_group_row_in_family(
            &refs,
            &held(c),
            &VendoredFamilyModel,
            &SelectContext::default(),
        );
        match (&c["expect"], got) {
            (J::Array(want), Ok(g)) => {
                let labels: Vec<String> = g.voices.into_iter().map(family_label).collect();
                let want: Vec<&str> = want.iter().map(|w| w.as_str().unwrap()).collect();
                assert_eq!(labels, want, "{id}");
                assert_eq!(
                    g.row_id.map(hex::encode),
                    c.get("row_id_hex").and_then(J::as_str).map(str::to_owned),
                    "{id}"
                );
            },
            (J::String(w), Err(GroupFault::SeveralRows)) if w == "several_rows" => {},
            (w, other) => panic!("{id}: want {w}, got {other:?}"),
        }
    }
}
